function farmHrModuleActive(module = selectedFarmModule()) {
  const id = String(module?.id || "");
  return id === "farm-people" || id.startsWith("farm-hr-") || id.startsWith("farm-people-");
}

function farmHrPersonRows() {
  const employees = farmRowsByKey("employees").map((row) => ({
    id: row.id,
    code: row.employee_code,
    name: row.full_name,
    source: "employees",
    personType: row.worker_type || "พนักงาน",
    paymentType: row.payment_type || (row.worker_type === "พนักงาน" ? "รายเดือน" : "รายวัน"),
    nationality: row.nationality || "ไทย",
    department: farmLookupLabel("departments", row.department_id),
    housing: farmLookupLabel("housing_units", row.default_housing_unit_id),
    dailyWage: n(row.daily_wage),
    monthlySalary: n(row.monthly_salary),
    contractRate: n(row.contract_rate),
    status: row.status || "active",
  }));
  const contractors = farmRowsByKey("contractors").map((row) => ({
    id: row.id,
    code: row.contractor_code,
    name: row.contractor_name,
    source: "contractors",
    personType: row.contractor_type || "ผู้รับเหมา",
    paymentType: row.payment_type || "รายเหมา",
    nationality: row.nationality || "ไทย",
    department: "ผู้รับเหมา",
    housing: "",
    dailyWage: 0,
    monthlySalary: 0,
    contractRate: n(row.default_contract_rate),
    status: row.status || "active",
  }));
  return [...employees, ...contractors].filter((row) => String(row.status).toLowerCase() !== "inactive");
}

function farmHrDocDaysLeft(row) {
  if (!row?.expiry_date) return null;
  const expiry = new Date(`${row.expiry_date}T00:00:00`);
  if (Number.isNaN(expiry.getTime())) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Math.ceil((expiry.getTime() - today.getTime()) / 86400000);
}

function farmHrDocumentRows() {
  return farmRowsByKey("worker_documents").map((row) => {
    const employee = farmHrEmployeeById(row.employee_id);
    const contractor = farmHrContractorById(row.contractor_id);
    const holder = employee || contractor || {};
    const daysLeft = farmHrDocDaysLeft(row);
    const alertDays = n(row.alert_days_before || 45);
    const status = daysLeft === null ? "unknown" : daysLeft < 0 ? "expired" : daysLeft <= alertDays ? "warning" : "valid";
    return {
      ...row,
      holderName: row.holder_name_snapshot || holder.full_name || holder.contractor_name || "-",
      nationalityText: row.nationality_snapshot || holder.nationality || "-",
      paymentText: row.payment_type_snapshot || holder.payment_type || "-",
      daysLeft,
      alertDays,
      alertStatus: row.renewal_status || status,
    };
  });
}

function farmHrDocumentTypeLabel(type) {
  return farmTranslateValue(type || "other") || type || "-";
}

function farmHrDocumentAlertLabel(row) {
  if (row.daysLeft === null) return "ไม่ระบุวันหมดอายุ";
  if (row.daysLeft < 0) return `หมดอายุแล้ว ${fmt(Math.abs(row.daysLeft))} วัน`;
  if (row.daysLeft <= 7) return `เร่งด่วน ${fmt(row.daysLeft)} วัน`;
  if (row.daysLeft <= 30) return `ภายใน 30 วัน`;
  if (row.daysLeft <= 60) return `ภายใน 60 วัน`;
  if (row.daysLeft <= 90) return `ภายใน 90 วัน`;
  return `เหลือ ${fmt(row.daysLeft)} วัน`;
}

function farmHrDocumentAlertClass(row) {
  if (row.daysLeft === null) return "muted";
  if (row.daysLeft < 0) return "danger";
  if (row.daysLeft <= 30) return "warning";
  return "ok";
}

function farmHrDocumentFocusRows(docs) {
  const order = { passport: 1, visa: 2, work_permit: 3, medical: 4, pink_card: 5 };
  return Object.values(docs.reduce((acc, row) => {
    const key = row.document_type || "other";
    if (!acc[key]) acc[key] = { type: key, total: 0, expired: 0, due30: 0, due90: 0 };
    acc[key].total += 1;
    if (row.daysLeft !== null && row.daysLeft < 0) acc[key].expired += 1;
    if (row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 30) acc[key].due30 += 1;
    if (row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 90) acc[key].due90 += 1;
    return acc;
  }, {})).sort((a, b) => (order[a.type] || 99) - (order[b.type] || 99) || String(a.type).localeCompare(String(b.type), "th"));
}

function renderFarmHrBoard(module, table) {
  const people = farmHrPersonRows();
  const daily = people.filter((row) => row.paymentType === "รายวัน");
  const monthly = people.filter((row) => row.paymentType === "รายเดือน");
  const contract = people.filter((row) => row.paymentType === "รายเหมา");
  const foreignPeople = people.filter(farmHrIsForeign);
  const docs = farmHrDocumentRows().filter((row) => farmHrIsForeign(row) || row.nationalityText !== "ไทย");
  const warningDocs = docs
    .filter((row) => row.daysLeft !== null && row.daysLeft <= row.alertDays)
    .sort((a, b) => (a.daysLeft ?? 9999) - (b.daysLeft ?? 9999));
  const expiredDocs = docs.filter((row) => row.daysLeft !== null && row.daysLeft < 0);
  const urgentDocs = docs.filter((row) => row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 7);
  const due30Docs = docs.filter((row) => row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 30);
  const due90Docs = docs.filter((row) => row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 90);
  const docFocusRows = farmHrDocumentFocusRows(docs);
  const dailyCost = daily.reduce((sum, row) => sum + row.dailyWage, 0);
  const monthlyCost = monthly.reduce((sum, row) => sum + row.monthlySalary, 0);
  const contractRate = contract.reduce((sum, row) => sum + row.contractRate, 0);
  const focusMap = {
    "farm-hr-dashboard": "ภาพรวม Dashboard HR รวมจำนวนคน เอกสารเตือน ลงเวลา ลา/OT ค่าแรง และทักษะทีม",
    "farm-people": "ข้อมูลบุคลากรรวมรายวัน รายเดือน รายเหมา บ้านพัก ทีมงาน และเอกสารต่างด้าวในหน้าเดียว",
    "farm-hr-org": "โครงสร้างองค์กร แผนก ทีม หัวหน้า และการผูกคนเข้าทีมเพื่อใช้งานต่อกับ Work Order",
    "farm-hr-teams": "ทีมทำงานสำหรับส่งต่อให้วางแผน สั่งงาน บันทึกงาน และคำนวณค่าแรงในงานจัดการสวนปาล์ม",
    "farm-hr-time": "Work & Time สำหรับลงเวลา กะงาน ขาด/สาย และข้อมูลจากงานจริง",
    "farm-hr-leave": "Leave & OT สำหรับคำขอลา OT และสถานะอนุมัติที่ส่งต่อเข้าค่าแรง",
    "farm-hr-payroll": "Compensation สำหรับเงินเดือน ค่าแรง เงินเพิ่ม/หัก และ snapshot ที่ล็อกผลคำนวณแล้ว",
    "farm-hr-talent": "Talent สำหรับอบรม ทักษะกิจกรรม และประเมินผลการทำงาน",
    "farm-people-daily": "โฟกัสคนงานรายวัน รวมต่างด้าว บ้านพัก ทีมงาน ลงเวลา และเอกสารหมดอายุ",
    "farm-people-monthly": "โฟกัสพนักงานรายเดือน แผนก ตำแหน่ง เงินเดือน ลา/OT และการอนุมัติ",
    "farm-people-contract": "โฟกัสผู้รับเหมา อัตราเหมา ทีมงาน และการผูกกับ Work Order",
    "farm-people-docs": "โฟกัส Passport / Visa / Work Permit / Pink Card พร้อมเตือนล่วงหน้า",
  };
  const hrAreas = [
    ["Dashboard HR", "ภาพรวมกำลังคน เอกสารเตือน เวลา ลา/OT และค่าแรง", "farm-hr-dashboard"],
    ["ข้อมูลบุคลากร", "พนักงานรายเดือน คนงานรายวัน ผู้รับเหมา บ้านพัก และเอกสารต่างด้าว", "farm-people"],
    ["เอกสารต่างด้าว", "Passport, Visa, Work Permit, ตรวจสุขภาพ และเตือนหมดอายุ", "farm-people-docs"],
    ["ทีมทำงาน", "ทีม หัวหน้า สมาชิก ทักษะกิจกรรม และการใช้งานใน Work Order", "farm-hr-teams"],
    ["Work & Time", "ลงเวลา กะงาน ลา OT และข้อมูลทำงานจริง", "farm-hr-time"],
    ["Compensation", "งวดเงินเดือน ค่าแรง เงินเพิ่ม/หัก และ snapshot ปิดงวด", "farm-hr-payroll"],
    ["Talent", "อบรม ทักษะกิจกรรม และผลประเมิน", "farm-hr-talent"],
  ];
  const flow = [
    ["01", "ข้อมูลบุคคล", "รหัส, ชื่อ, สัญชาติ, ประเภทจ่าย, แผนก, บ้านพัก"],
    ["02", "เอกสารต่างด้าว", "Passport, Visa, Work Permit, วันหมดอายุ, ผู้รับผิดชอบ"],
    ["03", "เวลา/ลา/OT", "ลงเวลาและคำขอ เพื่อส่งต่อค่าแรง"],
    ["04", "Snapshot ค่าแรง", "เมื่อปิดงวดแล้วไม่เปลี่ยนตามข้อมูลหลักใหม่"],
  ];
  const isDashboard = module.id === "farm-hr-dashboard";
  const isPeoplePage = module.id === "farm-people";
  const isDocPage = module.id === "farm-people-docs";
  const showPeopleSummary = isDashboard || isPeoplePage || isDocPage;
  const showHrFlow = isDashboard || isPeoplePage;
  const showDocumentSections = isDashboard || isDocPage;
  const showUsageLinks = isDashboard || isPeoplePage;
  return `
    <section class="hr-oneflow-board">
      <div class="section-head">
        <h3>งานบริหารบุคคล</h3>
        <span>${esc(focusMap[module.id] || module.description)}</span>
      </div>
      <div class="hr-area-grid">
        ${hrAreas.map((item) => `<button type="button" class="${module.id === item[2] ? "active" : ""}" data-view-jump="${esc(item[2])}">
          <strong>${esc(item[0])}</strong>
          <span>${esc(item[1])}</span>
        </button>`).join("")}
      </div>
      ${showPeopleSummary ? `<div class="hr-segment-grid">
        <article><span>รายวัน / คนงาน</span><strong>${fmt(daily.length)}</strong><small>ต่างด้าว ${fmt(daily.filter(farmHrIsForeign).length)} คน · ค่าแรงตั้งต้น ${fmt(dailyCost)}</small></article>
        <article><span>รายเดือน / พนักงาน</span><strong>${fmt(monthly.length)}</strong><small>เงินเดือนตั้งต้น ${fmt(monthlyCost)}</small></article>
        <article><span>รายเหมา / ผู้รับเหมา</span><strong>${fmt(contract.length)}</strong><small>อัตราเหมาตั้งต้น ${fmt(contractRate)}</small></article>
        <article><span>เอกสารต้องเตือน</span><strong>${fmt(warningDocs.length)}</strong><small>แรงงานต่างด้าวทั้งหมด ${fmt(foreignPeople.length)} คน</small></article>
      </div>` : ""}
      ${showHrFlow ? `<div class="hr-flow-grid">
        ${flow.map((item) => `<article><b>${item[0]}</b><strong>${esc(item[1])}</strong><span>${esc(item[2])}</span></article>`).join("")}
      </div>` : ""}
      ${showDocumentSections ? `<div class="hr-document-alert-grid">
        <article class="danger"><span>หมดอายุแล้ว</span><strong>${fmt(expiredDocs.length)}</strong><small>ต้องดำเนินการทันที</small></article>
        <article class="warning"><span>เร่งด่วน 7 วัน</span><strong>${fmt(urgentDocs.length)}</strong><small>ควรต่ออายุ / นัดตรวจ</small></article>
        <article><span>ภายใน 30 วัน</span><strong>${fmt(due30Docs.length)}</strong><small>รวม Work Permit และ Medical</small></article>
        <article><span>ภายใน 90 วัน</span><strong>${fmt(due90Docs.length)}</strong><small>ใช้วางแผนล่วงหน้า</small></article>
      </div>
      <div class="hr-two-col hr-document-center">
        <article class="farm-panel">
          <div class="section-head">
            <h3>สรุปเอกสารตามชนิด</h3>
            <button type="button" data-farm-hr-doc-new>เพิ่มเอกสาร</button>
          </div>
          <div class="table-wrap">
            <table class="mini-table">
              <thead><tr><th>เอกสาร</th><th>ทั้งหมด</th><th>หมดอายุ</th><th>30 วัน</th><th>90 วัน</th></tr></thead>
              <tbody>
                ${docFocusRows.map((row) => `<tr>
                  <td>${esc(farmHrDocumentTypeLabel(row.type))}</td>
                  <td class="num">${fmt(row.total)}</td>
                  <td class="num">${fmt(row.expired)}</td>
                  <td class="num">${fmt(row.due30)}</td>
                  <td class="num">${fmt(row.due90)}</td>
                </tr>`).join("") || `<tr><td colspan="5">ยังไม่มีข้อมูลเอกสาร</td></tr>`}
              </tbody>
            </table>
          </div>
        </article>
        <article class="farm-panel">
          <div class="section-head"><h3>ลำดับดำเนินการต่ออายุ</h3><span>อ้างอิงแนวคิด FWMS</span></div>
          <div class="hr-renewal-steps">
            <span><b>1</b> ตรวจรายชื่อแรงงานต่างด้าวและชนิดเอกสาร</span>
            <span><b>2</b> ดูวันหมดอายุและระดับเตือน 7/30/60/90 วัน</span>
            <span><b>3</b> มอบหมายผู้รับผิดชอบและเปลี่ยนสถานะเป็นกำลังต่ออายุ</span>
            <span><b>4</b> แนบไฟล์ใหม่และบันทึกวันหมดอายุใหม่</span>
          </div>
        </article>
      </div>
      <div class="hr-two-col">
        <article class="farm-panel">
          <div class="section-head"><h3>เตือนเอกสารแรงงานต่างด้าว</h3><span>เรียงตามวันหมดอายุ</span></div>
          <div class="table-wrap">
            <table class="mini-table">
              <thead><tr><th>ชื่อ</th><th>สัญชาติ</th><th>เอกสาร</th><th>หมดอายุ</th><th>คงเหลือ</th><th>สถานะ</th></tr></thead>
              <tbody>
                ${warningDocs.slice(0, 8).map((row) => `<tr>
                  <td>${esc(row.holderName)}</td>
                  <td>${esc(row.nationalityText)}</td>
                  <td>${esc(farmHrDocumentTypeLabel(row.document_type))}<small>${esc(row.document_no || "")}</small></td>
                  <td>${esc(row.expiry_date || "-")}</td>
                  <td>${esc(farmHrDocumentAlertLabel(row))}</td>
                  <td><span class="status-pill ${farmHrDocumentAlertClass(row)}">${esc(farmTranslateValue(row.alertStatus) || "-")}</span></td>
                </tr>`).join("") || `<tr><td colspan="6">ยังไม่มีเอกสารที่ต้องเตือน</td></tr>`}
              </tbody>
            </table>
          </div>
        </article>
        ${showUsageLinks ? `<article class="farm-panel">
          <div class="section-head"><h3>โครงสร้างที่นำไปใช้ต่อ</h3><span>ไม่รวมงานบริการอาคาร รถส่วนกลาง หรือพัสดุสำนักงาน</span></div>
          <div class="hr-link-list">
            <span><b>Work Order</b> ใช้ทีม, คนงาน, ผู้รับเหมา และทักษะกิจกรรม</span>
            <span><b>Payroll</b> ใช้ประเภทจ่ายและ snapshot อัตราตอนปิดงวด</span>
            <span><b>Housing</b> ใช้บ้านพักเพื่อกระจายค่าน้ำค่าไฟ</span>
            <span><b>Alert</b> ใช้ expiry_date + alert_days_before เพื่อเตือนต่ออายุเอกสาร</span>
          </div>
        </article>` : ""}
      </div>` : ""}
    </section>`;
}

function farmTeamLabel(team) {
  return [team?.team_code, team?.team_name].filter(Boolean).join(" - ") || team?.id || "-";
}

function farmTeamMemberPerson(member) {
  return farmLookup("employees", member.employee_id) || farmLookup("people", member.person_id) || farmLookup("contractors", member.contractor_id) || {};
}

function farmTeamMemberLabel(member) {
  const person = farmTeamMemberPerson(member);
  return person.full_name || person.person_name || person.contractor_name || person.employee_code || person.person_code || person.contractor_code || member.employee_id || member.person_id || "-";
}

function farmTeamEmployeeLabel(employee) {
  return [employee?.employee_code, employee?.full_name].filter(Boolean).join(" - ") || employee?.id || "-";
}

function renderFarmTeamsBoard() {
  const teamTable = farmTableByKey("teams");
  const memberTable = farmTableByKey("team_members");
  const skillTable = farmTableByKey("team_activity_skills");
  const employeeTable = farmTableByKey("employees");
  const query = state.farmFilters.query.trim().toLowerCase();
  const statusOk = (row) => state.farmFilters.status === "all" || String(row.status || "").toLowerCase() === state.farmFilters.status;
  const textOk = (row) => !query || Object.values(row).join(" ").toLowerCase().includes(query);
  const allTeams = farmRows(teamTable);
  const allMembers = farmRows(memberTable);
  const allEmployees = farmRows(employeeTable);
  const skills = farmRows(skillTable);
  const workOrders = farmRowsByKey("work_orders");
  const teams = allTeams
    .filter((row) => statusOk(row) && textOk(row))
    .sort((a, b) => String(a.team_code || "").localeCompare(String(b.team_code || ""), "th", { numeric: true }));
  const selectedTeamId = teams.some((team) => team.id === state.farmSelectedTeamId)
    ? state.farmSelectedTeamId
    : (teams[0]?.id || "");
  const selectedTeam = allTeams.find((team) => team.id === selectedTeamId);
  const employees = allEmployees
    .filter((row) => statusOk(row) && textOk(row))
    .sort((a, b) => String(a.employee_code || "").localeCompare(String(b.employee_code || ""), "th", { numeric: true })
      || String(a.full_name || "").localeCompare(String(b.full_name || ""), "th", { numeric: true }));
  const members = allMembers
    .filter((row) => {
      const team = allTeams.find((item) => item.id === row.team_id) || {};
      const selectedOk = !selectedTeamId || row.team_id === selectedTeamId;
      return selectedOk && statusOk(row) && (textOk(row) || textOk(team) || farmTeamMemberLabel(row).toLowerCase().includes(query));
    })
    .sort((a, b) => String(a.team_id || "").localeCompare(String(b.team_id || ""), "th", { numeric: true })
      || String(a.member_role || "").localeCompare(String(b.member_role || ""), "th", { numeric: true }));
  const teamRows = teams.map((team) => {
    const teamMembers = allMembers.filter((member) => member.team_id === team.id);
    const supervisor = farmLookup("employees", team.supervisor_employee_id);
    const contractor = farmLookup("contractors", team.contractor_id);
    const skillCount = skills.filter((skill) => skill.team_id === team.id).length;
    return `
      <tr class="${team.id === selectedTeamId ? "is-selected team-choice-row" : "team-choice-row"}" data-team-drop="${esc(team.id)}" data-farm-team-row="${esc(team.id)}" title="คลิกเพื่อดูสมาชิกทีม / ลากพนักงานมาวางเพื่อเพิ่มเข้าทีม">
        <td><strong>${esc(team.team_code || "-")}</strong></td>
        <td>${esc(team.team_name || "-")}</td>
        <td>${esc(farmTranslateValue(team.team_type) || "-")}</td>
        <td>${esc(supervisor ? farmRecordLabel(farmTableByKey("employees"), supervisor) : "-")}</td>
        <td>${esc(contractor ? farmRecordLabel(farmTableByKey("contractors"), contractor) : "-")}</td>
        <td class="num">${fmt(teamMembers.length)}</td>
        <td class="num">${fmt(skillCount)}</td>
        <td>${esc(farmTranslateValue(team.status) || "-")}</td>
      </tr>`;
  }).join("");
  const employeeRows = employees.map((employee) => {
    const memberTeams = allMembers
      .filter((member) => member.employee_id === employee.id && String(member.is_active) !== "false")
      .map((member) => allTeams.find((team) => team.id === member.team_id))
      .filter(Boolean);
    return `
      <tr draggable="true" data-team-employee-drag="${esc(employee.id)}" title="ลากไปวางบนทีมทำงาน">
        <td><strong>${esc(employee.employee_code || "-")}</strong></td>
        <td>${esc(employee.full_name || "-")}</td>
        <td>${esc(employee.worker_type || employee.position || "-")}</td>
        <td>${esc(memberTeams.map((team) => team.team_code || team.team_name).join(", ") || "-")}</td>
      </tr>`;
  }).join("");
  const memberRows = members.map((member) => {
    const team = allTeams.find((item) => item.id === member.team_id);
    return `
      <tr data-farm-team-member-row="${esc(member.id)}">
        <td><strong>${esc(farmTeamMemberLabel(member))}</strong></td>
        <td>${esc(team ? farmTeamLabel(team) : "-")}</td>
        <td>${esc(member.member_role || "-")}</td>
        <td>${esc(member.start_date || "-")}</td>
        <td>${esc(member.end_date || "-")}</td>
        <td>${String(member.is_active) === "false" ? "หยุดใช้" : "ใช้งาน"}</td>
      </tr>`;
  }).join("");
  const summaryRows = allTeams
    .filter((team) => statusOk(team) && textOk(team))
    .flatMap((team) => {
      const teamMembers = allMembers.filter((member) => member.team_id === team.id);
      const teamSkills = skills.filter((skill) => skill.team_id === team.id);
      const orderCount = workOrders.filter((order) => order.team_id === team.id).length;
      if (!teamSkills.length) {
        return [`
        <tr data-farm-team-summary-row="${esc(team.id)}">
          <td><strong>${esc(farmTeamLabel(team))}</strong></td>
          <td>${esc(farmTranslateValue(team.team_type) || "-")}</td>
          <td>${esc(farmLookupLabel("employees", team.supervisor_employee_id) || "-")}</td>
          <td class="num">${fmt(teamMembers.length)}</td>
          <td>${esc(farmLookupLabel("activity_groups", team.default_activity_group_id) || "-")}</td>
          <td>-</td>
          <td>-</td>
          <td class="num">${fmt(orderCount)}</td>
          <td>${esc(farmTranslateValue(team.status) || "-")}</td>
        </tr>`];
      }
      return teamSkills.map((skill) => `
        <tr data-farm-team-skill-row="${esc(skill.id)}">
          <td><strong>${esc(farmTeamLabel(team))}</strong></td>
          <td>${esc(farmTranslateValue(team.team_type) || "-")}</td>
          <td>${esc(farmLookupLabel("employees", team.supervisor_employee_id) || "-")}</td>
          <td class="num">${fmt(teamMembers.length)}</td>
          <td>${esc(farmLookupLabel("activities", skill.activity_id) || farmLookupLabel("activity_groups", team.default_activity_group_id) || "-")}</td>
          <td>${esc(farmTranslateValue(skill.skill_level) || "-")}</td>
          <td>${esc(farmTranslateValue(skill.rate_group) || "-")}</td>
          <td class="num">${fmt(orderCount)}</td>
          <td>${esc(farmTranslateValue(skill.status || team.status) || "-")}</td>
        </tr>`);
    }).join("");
  return `
    <section class="farm-activity-board farm-team-board">
      <div class="farm-activity-toolbar">
        <label>ค้นหา<input id="farmSearch" type="search" value="${esc(state.farmFilters.query)}" placeholder="ค้นหาทีม หัวหน้า สมาชิก กิจกรรม"></label>
        <label>สถานะ
          <select id="farmStatusFilter">
            ${FARM_STATUS_OPTIONS.map((status) => `<option value="${esc(status)}"${state.farmFilters.status === status ? " selected" : ""}>${esc(farmTranslateValue(status))}</option>`).join("")}
          </select>
        </label>
        <label>Role
          <select id="farmRoleFilter">
            ${FARM_ROLES.map((role) => `<option value="${esc(role)}"${state.farmFilters.role === role ? " selected" : ""}>${esc(farmTranslateValue(role))}</option>`).join("")}
          </select>
        </label>
      </div>
      <div class="farm-team-split">
        <article class="farm-panel farm-activity-table-card">
          <div class="section-head">
            <h3>ตารางทีมทำงาน</h3>
            <span>ลากพนักงานมาวางบนแถวทีม</span>
            <button type="button" data-farm-team-add="teams">เพิ่มทีม</button>
          </div>
          <div class="table-wrap farm-activity-table-wrap">
            <table class="mini-table farm-table">
              <thead><tr><th>รหัส</th><th>ทีม</th><th>ประเภท</th><th>หัวหน้า</th><th>ผู้รับเหมา</th><th>สมาชิก</th><th>ทักษะ</th><th>สถานะ</th></tr></thead>
              <tbody>${teamRows || `<tr><td colspan="8">ไม่พบทีมทำงาน</td></tr>`}</tbody>
            </table>
          </div>
        </article>
        <article class="farm-panel farm-activity-table-card">
          <div class="section-head">
            <h3>พนักงานทั้งหมด</h3>
            <span>ลากเข้าทีมได้ทันที</span>
          </div>
          <div class="table-wrap farm-activity-table-wrap">
            <table class="mini-table farm-table">
              <thead><tr><th>รหัส</th><th>ชื่อ</th><th>ประเภท</th><th>ทีมปัจจุบัน</th></tr></thead>
              <tbody>${employeeRows || `<tr><td colspan="4">ไม่พบพนักงาน</td></tr>`}</tbody>
            </table>
          </div>
        </article>
        <article class="farm-panel farm-activity-table-card">
          <div class="section-head">
            <h3>ตารางสมาชิกทีม</h3>
            <span>${selectedTeam ? `ทีมที่เลือก: ${esc(farmTeamLabel(selectedTeam))}` : "เลือกทีมจากตารางทีมทำงาน"}</span>
            <button type="button" data-farm-team-add="team_members">เพิ่มสมาชิก</button>
          </div>
          <div class="table-wrap farm-activity-table-wrap">
            <table class="mini-table farm-table">
              <thead><tr><th>ชื่อ</th><th>ทีม</th><th>หน้าที่</th><th>เริ่ม</th><th>สิ้นสุด</th><th>สถานะ</th></tr></thead>
              <tbody>${memberRows || `<tr><td colspan="6">ไม่พบสมาชิกทีม</td></tr>`}</tbody>
            </table>
          </div>
        </article>
      </div>
      <section class="farm-panel">
        <div class="section-head">
          <h3>ตารางทีมในสวนปาล์ม</h3>
          <span>ทีมที่ถูกนำไปใช้ต่อในวางแผน สั่งงาน และบันทึกงานผ่าน <code>work_orders.team_id</code></span>
          <button type="button" data-farm-team-add="team_activity_skills">เพิ่มทักษะกิจกรรม</button>
        </div>
        <div class="table-wrap farm-activity-bottom-wrap">
          <table class="mini-table farm-table">
            <thead><tr><th>ทีม</th><th>ประเภท</th><th>หัวหน้า</th><th>สมาชิก</th><th>กิจกรรม</th><th>ระดับ</th><th>กลุ่มเรท</th><th>Work Order</th><th>สถานะ</th></tr></thead>
            <tbody>${summaryRows || `<tr><td colspan="9">ไม่พบรายการทีม</td></tr>`}</tbody>
          </table>
        </div>
      </section>
    </section>
    ${renderFarmActivityModal()}`;
}

function farmBudgetGroupCount(rows, keyFn) {
  const map = new Map();
  for (const row of rows || []) {
    const label = keyFn(row);
    map.set(label, (map.get(label) || 0) + 1);
  }
  return [...map.entries()].map(([label, value]) => ({ label, value }));
}

function farmBudgetContractState() {
  if (!state.farmBudgetContract) {
    state.farmBudgetContract = {
      query: "",
      contractType: "Role Based Compounded",
      startDate: "",
      endDate: "",
      multiArea: false,
      selectedBlocks: [],
      selectedActivities: [],
      selectedMaterials: [],
      selectedVehicles: [],
      selectedWorkers: [],
      areaEstateId: "",
      areaZoneId: "",
      areaPlotId: "",
      rateType: "labor",
      calculationMethod: "per_rai",
      comparisonBasis: "area_rai",
      unitName: "ไร่",
      rateAmount: "",
      baseMaterialQuantity: "",
      baseUsageUnit: "",
      baseMaterialBasis: "",
      performancePerUom: "",
      budgetFiscalYear: farmBudgetFiscalYear(farmToday()),
      budgetName: `อัตรางบประมาณ ${farmBudgetFiscalYear(farmToday())}`,
      budgetStartDate: `${new Date().getFullYear()}-01-01`,
      budgetEndDate: `${new Date().getFullYear()}-12-31`,
      budgetStatus: "active",
    };
  }
  const picks = state.farmBudgetContract;
  if (!Array.isArray(picks.extraRates)) {
    picks.extraRates = [];
  }
  if (!picks.contractName) picks.contractName = "";
  if (!picks.approvalStatus) picks.approvalStatus = "approved";
  if (!picks.approvalScope) picks.approvalScope = "standard_contract";
  if (!picks.approvalMode) picks.approvalMode = "not_required";
  if (!picks.externalContractNo) picks.externalContractNo = "";
  if (!picks.supplierContractNo) picks.supplierContractNo = "";
  if (!picks.dataGroup) picks.dataGroup = "";
  if (!picks.areaEstateId) picks.areaEstateId = "";
  if (!picks.areaZoneId) picks.areaZoneId = "";
  if (!picks.areaPlotId) picks.areaPlotId = "";
  if (!Array.isArray(picks.selectedVehicles)) picks.selectedVehicles = [];
  if (picks.baseMaterialQuantity === undefined) picks.baseMaterialQuantity = "";
  if (!picks.baseUsageUnit) picks.baseUsageUnit = "";
  if (!picks.baseMaterialBasis) picks.baseMaterialBasis = "";
  if (picks.performancePerUom === undefined) picks.performancePerUom = "";
  if (!picks.budgetFiscalYear) picks.budgetFiscalYear = farmBudgetFiscalYear(farmToday());
  if (!picks.budgetName) picks.budgetName = `อัตรางบประมาณ ${picks.budgetFiscalYear}`;
  if (!picks.budgetStartDate) picks.budgetStartDate = `${new Date().getFullYear()}-01-01`;
  if (!picks.budgetEndDate) picks.budgetEndDate = `${new Date().getFullYear()}-12-31`;
  if (!picks.budgetStatus) picks.budgetStatus = "active";
  return state.farmBudgetContract;
}

function farmWorkPlanState() {
  if (!state.farmWorkPlan) {
    state.farmWorkPlan = {};
  }
  const picks = state.farmWorkPlan;
  if (!Array.isArray(picks.selectedBlocks)) picks.selectedBlocks = [];
  if (!Array.isArray(picks.selectedActivities)) picks.selectedActivities = [];
  if (!Array.isArray(picks.selectedMaterials)) picks.selectedMaterials = [];
  if (!Array.isArray(picks.selectedVehicles)) picks.selectedVehicles = [];
  if (!Array.isArray(picks.selectedWorkers)) picks.selectedWorkers = [];
  if (!picks.selectedBudgetRateId) picks.selectedBudgetRateId = "";
  if (!picks.workMode) picks.workMode = "single";
  if (!picks.repeatMode) picks.repeatMode = "none";
  if (!picks.referenceOrderId) picks.referenceOrderId = "";
  if (!picks.startDate) picks.startDate = farmToday();
  if (!picks.endDate) picks.endDate = picks.startDate || farmToday();
  if (!picks.calcMode) picks.calcMode = "rate";
  return picks;
}

function farmBudgetFiscalYear(dateValueText = "") {
  const year = n(String(dateValueText || "").slice(0, 4)) || new Date().getFullYear();
  return String(year + 543);
}

function farmBudgetYearId(fiscalYear = "") {
  return `budget-year-${farmBudgetSafeCode(fiscalYear || farmBudgetFiscalYear(farmToday()))}`.slice(0, 120);
}

async function saveFarmBudgetYearSetting({ silent = false } = {}) {
  const picks = farmBudgetContractState();
  const fiscalYear = String(picks.budgetFiscalYear || farmBudgetFiscalYear(picks.budgetStartDate || farmToday())).trim();
  if (!fiscalYear) {
    state.farmSyncStatus = "error";
    state.farmSyncMessage = "กรุณาระบุปีอัตรางบประมาณก่อนบันทึก";
    render();
    return null;
  }
  const table = farmTableByKey("budget_years");
  const existing = farmRowsByKey("budget_years").find((row) => String(row.fiscal_year) === fiscalYear);
  const row = {
    id: existing?.id || farmBudgetYearId(fiscalYear),
    moduleId: "farm-budget",
    tableId: "budget_years",
    fiscal_year: fiscalYear,
    budget_name: picks.budgetName || `อัตรางบประมาณ ${fiscalYear}`,
    effective_from: picks.budgetStartDate || "",
    effective_to: picks.budgetEndDate || "",
    status: picks.budgetStatus || "active",
    note: "สร้างจากหน้าอัตรางบประมาณ",
    updatedAt: new Date().toISOString(),
  };
  if (!silent) {
    state.farmSyncBusy = true;
    state.farmSyncStatus = "";
    state.farmSyncMessage = `กำลังบันทึกปีอัตรางบประมาณ ${fiscalYear}...`;
    render();
  }
  try {
    const saved = await persistFarmRowToDatabase(table, row);
    if (!silent) {
      state.farmSyncStatus = "success";
      state.farmSyncMessage = `บันทึกปีอัตรางบประมาณ ${fiscalYear} แล้ว`;
      await loadFarmTablesFromDatabase({ silent: true, tables: farmDatabaseTablesForView("farm-budget") });
    }
    return saved.row || row;
  } catch (error) {
    state.farmSyncStatus = "error";
    state.farmSyncMessage = `บันทึกปีอัตรางบประมาณไม่สำเร็จ: ${error.message}`;
    return null;
  } finally {
    if (!silent) {
      state.farmSyncBusy = false;
      render();
    }
  }
}

